def validate_hosted_asof_window(
    user_vars: dict[str, str], *, today: date | None = None,
) -> tuple[date, date]:
    """Validate the explicit historical window used by the hosted A-share preset."""
    start_raw = user_vars.get("start_date")
    end_raw = user_vars.get("end_date")
    if not isinstance(start_raw, str) or not isinstance(end_raw, str):
        raise ValueError("mona_ashare_research requires explicit start_date and end_date")
    try:
        start = date.fromisoformat(start_raw)
        end = date.fromisoformat(end_raw)
    except ValueError as exc:
        raise ValueError("start_date and end_date must be valid YYYY-MM-DD dates") from exc
    if start.isoformat() != start_raw or end.isoformat() != end_raw:
        raise ValueError("start_date and end_date must use canonical YYYY-MM-DD dates")
    if start > end:
        raise ValueError("start_date must be on or before end_date")
    if end > (today or date.today()):
        raise ValueError("end_date cannot be in the future for hosted Swarm grounding")
    return start, end


def fetch_grounding_snapshot(
    symbols: Iterable[str],
    *,
    start_date: date,
    end_date: date,
    today: date | None = None,
) -> tuple[dict[str, list[dict]], dict[str, dict[str, Any]]]:
    """Fetch a hosted historical snapshot with the market-data provenance intact.

    The returned metadata separates requested dates/interval from actual row
    coverage. It copies provider/source fields only when the data API returns
    them; in particular it never treats ``source`` as a provider name.
    """
    start, end = validate_hosted_asof_window(
        {"start_date": start_date.isoformat(), "end_date": end_date.isoformat()},
        today=today,
    )
    symbol_list = list(symbols)
    if not symbol_list:
        return {}, {}

    from src.market_data import fetch_market_data_json

    payload = json.loads(
        fetch_market_data_json(
            codes=symbol_list,
            start_date=start.isoformat(),
            end_date=end.isoformat(),
            source="auto",
            interval="1D",
            max_rows=0,
            include_provenance=True,
        )
    )
    if not isinstance(payload, dict):
        raise ValueError("market-data snapshot did not return a JSON object")

    provenance_by_symbol = payload.get("_provenance", {})
    fetched: dict[str, list[dict]] = {}
    metadata: dict[str, dict[str, Any]] = {}
    for symbol in symbol_list:
        value = payload.get(symbol, [])
        rows = value if isinstance(value, list) else []
        dates: list[str] = []
        for row in rows:
            if not isinstance(row, dict):
                raise ValueError(f"market-data snapshot returned a malformed row for {symbol}")
            raw_date = str(row.get("trade_date") or row.get("timestamp") or "")[:10]
            try:
                row_date = date.fromisoformat(raw_date)
            except ValueError as exc:
                raise ValueError(f"market-data snapshot returned an invalid date for {symbol}") from exc
            if row_date < start or row_date > end:
                raise ValueError(f"market-data snapshot returned a row outside the requested window for {symbol}")
            dates.append(raw_date)
        if rows:
            fetched[symbol] = rows
        raw_provenance = provenance_by_symbol.get(symbol) if isinstance(provenance_by_symbol, dict) else None
        provenance = raw_provenance if isinstance(raw_provenance, dict) else None
        metadata[symbol] = {
            "status": "ok" if rows else "unavailable",
            "request": {
                "source": "auto",
                "interval": "1D",
                "start_date": start.isoformat(),
                "end_date": end.isoformat(),
            },
            "coverage": {
                "start_date": min(dates) if dates else None,
                "end_date": max(dates) if dates else None,
                "row_count": len(rows),
            },
            "provenance": provenance,
        }
    return fetched, metadata


